 const wallMap=texture.clone();wallMap.repeat.set(1.4,2.4);let floorMap=texture.clone();floorMap.repeat.set(12,12);if(unique){floorMap=await new THREE.TextureLoader().loadAsync('../../assets/stone-floor-unique.webp');floorMap.colorSpace=THREE.SRGBColorSpace;floorMap.anisotropy=8;}
 const stone=new THREE.MeshStandardMaterial({map:wallMap,color:0x8a8d92,roughness:.88,bumpMap:wallMap,bumpScale:.09}),darkStone=new THREE.MeshStandardMaterial({map:wallMap,color:0x404957,roughness:.65,bumpMap:wallMap,bumpScale:.05}),gold=new THREE.MeshStandardMaterial({color:0x98815a,metalness:unique?.2:.78,roughness:unique?.8:.38});
